proguardAdditions.insert:

-keep class com.taptap.sdk.battle.** { *; }
-keep interface com.taptap.sdk.battle.** { *; }
-keep class com.taptap.sdk.onlinebattle.internal.** { *; }

-keep class com.taptap.sdk.battle.internal.ue.** { *; }
-keepclassmembers class com.taptap.sdk.battle.internal.ue.** { *; }

-keep @android.support.annotation.Keep class * { *; }
-keep @androidx.annotation.Keep class * { *; }

-keepclasseswithmembernames class * {
    native <methods>;
}

-keepattributes *Annotation*
-keepattributes Signature
-keepattributes Exceptions
-keepattributes SourceFile,LineNumberTable

buildGradleAdditions.insert:

dependencies {
    // Keep this version aligned with Android/sdk/tap-battle/module.json.
    // It must be published with TapBattleUERouter included.
    implementation 'com.taptap.sdk:tap-battle:4.11.0'
}

gameActivityClassAdditions.insert:

public String routeToTapBattle(String requestJson, EngineBridgeCallback callback) {
    try {
        return TapBattleUERouter.route(this, requestJson, callback);
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapBattle route error: " + e.getMessage(), e);
        return "{\"success\":false,\"message\":\"TapBattle route error\"}";
    }
}
